background: rgba(255, 3, 77, 0.12);
border: 1px solid #FF034D;
color: #ffffff;
padding: 12px 18px;
border-radius: 8px;
margin: 15px auto 5px auto;
max-width: 780px;
font-family: 'Inter', sans-serif;
font-size: 13.5px;
line-height: 1.4;
text-align: center;
box-shadow: 0 4px 12px rgba(255, 3, 77, 0.15);

@keyframes arrow-flash {
  0%, 100% { opacity: 0; transform: translate(0, 0); }
  50% { opacity: 1; transform: translate(-10px, 10px); }
}
.tutorial-arrow {
  position: absolute;
  pointer-events: none;
  z-index: 10000;
  width: 60px;
  height: 60px;
  animation: arrow-flash 0.6s ease-in-out infinite;
}

.yes-no-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 15px;
  font-family: 'Inter', sans-serif;
}
.yes-no-table th, .yes-no-table td {
  padding: 10px;
  text-align: center;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
}
.yes-no-table th {
  color: #94a3b8;
  font-weight: 600;
  font-size: 13px;
  text-transform: uppercase;
}
.yes-no-table td:first-child {
  text-align: left;
  font-weight: 700;
  color: #e2e8f0;
}

.btn-choice {
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.1);
  color: #e2e8f0;
  padding: 6px 16px;
  border-radius: 6px;
  cursor: pointer;
  font-weight: 600;
  transition: all 0.2s ease;
  min-width: 60px;
}
.btn-choice:hover {
  background: rgba(255, 255, 255, 0.15);
}
.btn-choice.active-yes {
  background: #10b981;
  border-color: #10b981;
  color: white;
  box-shadow: 0 0 10px rgba(16, 185, 129, 0.4);
}
.btn-choice.active-no {
  background: #ef4444;
  border-color: #ef4444;
  color: white;
  box-shadow: 0 0 10px rgba(239, 68, 68, 0.4);
}

.btn-validate {
  display: block;
  width: 100%;
  margin-top: 20px;
  background: #8b5cf6;
  border: none;
  color: white;
  padding: 12px;
  border-radius: 8px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.2s;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}
.btn-validate:hover {
  background: #7c3aed;
  box-shadow: 0 0 15px rgba(124, 58, 237, 0.4);
}

.statement-container {
  margin-top: 15px;
  display: flex;
  flex-direction: column;
  gap: 15px;
}
.statement-row {
  background: rgba(255, 255, 255, 0.02);
  border: 1px solid rgba(255, 255, 255, 0.05);
  padding: 12px;
  border-radius: 8px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  transition: border-color 0.3s;
}
.statement-row.correct-locked {
  border-color: rgba(16, 185, 129, 0.4);
  background: rgba(16, 185, 129, 0.03);
}
.statement-text {
  font-size: 13.5px;
  color: #cbd5e1;
  line-height: 1.4;
}
.statement-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}

.tutorial-overlay {
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(15, 23, 42, 0.85);
  backdrop-filter: blur(8px);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 9999;
}
.tutorial-popup {
  background: #0f172a;
  border: 1px solid rgba(255, 255, 255, 0.15);
  border-radius: 16px;
  padding: 30px;
  max-width: 500px;
  width: 90%;
  box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5);
  text-align: center;
}
.tutorial-popup h3 {
  margin-top: 0;
  font-size: 20px;
  font-weight: 800;
  color: #fff;
}
.tutorial-popup p {
  font-size: 14.5px;
  color: #94a3b8;
  line-height: 1.6;
  margin-bottom: 20px;
}
.tutorial-btn {
  background: #ff034d;
  border: none;
  color: white;
  padding: 10px 24px;
  border-radius: 8px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.2s;
}
.tutorial-btn:disabled {
  background: #475569;
  cursor: not-allowed;
  opacity: 0.6;
}

.feedback-box {
  background: rgba(255, 255, 255, 0.05);
  border-left: 4px solid #8b5cf6;
  padding: 12px;
  border-radius: 4px;
  font-size: 13.5px;
  color: #e2e8f0;
  line-height: 1.4;
  margin-top: 10px;
  animation: fadeIn 0.3s ease;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(5px); }
  to { opacity: 1; transform: translateY(0); }
}
